<template><section class="application-panel admin-progress-panel" aria-labelledby="admin-progress-title"><header class="admin-progress-header"><div><p class="application-eyebrow">Admin review progress and decision</p><h2 id="admin-progress-title">What happens next?</h2></div><strong>{{ completedCount }} of 3 reviews completed</strong></header>
  <div class="admin-progress-bar" role="progressbar" aria-label="Completed independent reviews" :aria-valuenow="completedCount" aria-valuemin="0" aria-valuemax="3"><span v-for="number in 3" :key="number" :class="{ complete: number <= completedCount }">Review {{ number }} · {{ number <= completedCount ? 'complete' : 'remaining' }}</span></div>
  <dl class="admin-progress-metrics"><div><dt>Standard requirement</dt><dd>3 independent reviews</dd></div><div><dt>Slots claimed</dt><dd>{{ claimedCount }} of 3</dd></div><div><dt>Reviews completed</dt><dd>{{ completedCount }} of 3</dd></div><div><dt>Reviews remaining</dt><dd>{{ remainingCount }}</dd></div><div><dt>Serious concern</dt><dd>{{ application.everHadConcern ? 'Raised — Admin response required' : 'None recorded' }}</dd></div><div><dt>Eligibility clarification</dt><dd>{{ application.everHadEligibilityIssue ? 'Raised — Admin response required' : 'None recorded' }}</dd></div><div><dt>Decision status</dt><dd>{{ decisionStatus }}</dd></div></dl>
  <p class="admin-next-step" role="status"><strong>Recommended next step:</strong> {{ nextStep }}</p>
  <div class="admin-slot-grid"><article v-for="slot in application.reviewerSlots" :key="slot.slot"><span>Review slot {{ slot.slot }}</span><strong>{{ slot.reviewerName || 'No reviewer assigned' }}</strong><p>{{ slotStatus(slot) }}</p><small>{{ slot.reviewLabel }}</small><template v-if="slot.state === 'submitted'"><strong>{{ scoreSummary(slot) }}</strong><span v-if="slot.seriousConcern" class="concern-warning">Serious concern raised</span><small>Submitted {{ formatDate(slot.submittedAt) }}</small></template></article></div>
  <section class="two-review-card" aria-labelledby="two-review-title"><h3 id="two-review-title">Are two reviews enough?</h3><p>Early acceptance can be considered after two completed reviews. Both must individually score at least 85% and neither may contain a serious concern.</p><ul><li><strong>Two reviews completed:</strong> {{ yesNo(completedCount === 2) }}</li><li><strong>First completed review at least 85%:</strong> {{ thresholdCheck(completedSlots[0]) }}</li><li><strong>Second completed review at least 85%:</strong> {{ thresholdCheck(completedSlots[1]) }}</li><li><strong>No current or historical serious concern:</strong> {{ yesNo(!application.everHadConcern) }}</li><li><strong>Eligible for early acceptance:</strong> {{ yesNo(earlyEligible) }}</li></ul>
    <div v-if="earlyEligible" class="eligibility-message"><strong>Two reviews meet the early-acceptance standard.</strong><p>A third review is optional if an admin confirms that the existing evidence is sufficient.</p></div><p v-else-if="completedCount >= 2 && completedSlots.some((slot) => slot.percentage < 85)">The two-review early-acceptance standard has not been met. A third review is still required for the normal automated process.</p><p v-else-if="application.everHadConcern" class="concern-warning">Admin response required. Early and automatic acceptance remain blocked because a serious concern was raised.</p>
  </section>
  <div class="admin-decision-actions"><button v-if="earlyEligible" type="button" @click="action='early'">Accept after two reviews</button><button v-if="availableSlot && !ownSlot" type="button" @click="completeReview">{{ application.adminInformed ? 'Complete an informed admin review' : completedCount === 2 ? 'Complete the third review myself' : 'Review the application myself' }}</button><RouterLink v-if="ownSlot" class="application-action-link" :to="reviewRoute">Start or continue my review</RouterLink><button type="button" @click="wait">Wait for the third reviewer</button><button v-if="completedCount" type="button" @click="reveal">View completed reviews</button><button v-if="canBypass" type="button" class="danger-muted" @click="action='bypass'">Bypass reviews and progress to induction</button><RouterLink v-if="application.id === 'APP-DEMO-0001'" class="application-action-link" :to="{ name: 'BookingsInvite', params: { invitationToken: 'DEMO-SUPERADMIN-INDUCTION' } }">Open demo induction booking</RouterLink></div>
  <section v-if="application.id === 'APP-DEMO-0001'" class="email-preview"><span class="demo-data-badge">Demo only — no email has been sent</span><h3>Induction invitation preview</h3><p><strong>Recipient:</strong> superadmin@projectrespawn.com</p><p><strong>Booking type:</strong> Induction</p><p>Use the demo invitation button, simulate signing in with the matching verified account, then select a date, time, and available staff member in that order.</p></section>
  <details class="demo-scenario-tools"><summary>Demo scenario tools</summary><p>These Admin-only controls use the normal in-memory claim, score and submission functions.</p><div><button type="button" @click="scenario('strong')">Load two strong completed reviews</button><button type="button" @click="scenario('mixed')">Load two mixed reviews</button><button type="button" @click="scenario('concern')">Load two strong reviews with a concern</button><button type="button" @click="scenario('clarification')">Load strong reviews with clarification</button><button type="button" @click="scenario('three-strong')">Load three reviews at least 85%</button><button type="button" @click="scenario('three-35')">Load three reviews at exactly 35%</button><button type="button" @click="scenario('three-low')">Load three reviews below 35%</button><button type="button" @click="reset">Reset demo workflow</button></div></details>
  <DemoActionModal :open="Boolean(action)" :title="action === 'early' ? 'Accept after two reviews' : 'Senior administrative bypass'" :description="action === 'early' ? 'Confirm that the existing evidence is sufficient and waive the third review.' : 'This override is separate from qualifying for early acceptance.'" :warning="action === 'early' ? 'Any unfinished third-slot claim or draft will close. Both submitted reviews are preserved.' : 'The normal review process will be overridden and unfinished work closed.'" :confirm-label="action === 'early' ? 'Accept and waive third review' : 'Bypass and progress to induction'" @cancel="action=''" @confirm="confirmAction" />
</section></template>
  <script>import DemoActionModal from './DemoActionModal.vue'; import { acceptEarly, adminBypass, claimReview, demoWorkflow, isEarlyAcceptanceEligible, loadDemoReviewScenario, resetDemoWorkflow, revealCompletedReviews, waitForThirdReview } from '../applicationAdminData.js'; export default { name: 'AdminReviewProgressPanel', components: { DemoActionModal }, props: { application: { type: Object, required: true } }, emits: ['reload'], data: () => ({ workflow: demoWorkflow, action: '' }), computed: { completedSlots() { return this.application.reviewerSlots.filter((slot) => slot.state === 'submitted'); }, completedCount() { return this.completedSlots.length; }, claimedCount() { return this.application.reviewerSlots.filter((slot) => !['available','closed'].includes(slot.state)).length; }, remainingCount() { return Math.max(0, 3 - this.completedCount); }, earlyEligible() { this.workflow.revision; return isEarlyAcceptanceEligible(); }, availableSlot() { return this.application.reviewerSlots.some((slot) => slot.state === 'available'); }, ownSlot() { return this.application.reviewerSlots.find((slot) => slot.reviewerId === 'admin-demo'); }, reviewRoute() { return { name: 'AdminApplicationReview', params: { applicationId: this.application.id } }; }, canBypass() { return ['awaiting-review','under-review','awaiting-admin-decision','admin-response-required','automatically-declined'].includes(this.application.status); }, decisionStatus() { if (this.application.status === 'admin-response-required') return 'Admin response required'; if (this.application.finalPercentage !== null) return this.application.outcome === 'qualified-induction' ? 'Automatic induction calculated' : this.application.outcome === 'automatic-decline' ? 'Automatically declined' : 'Admin decision required'; if (this.earlyEligible) return 'Eligible for early acceptance'; return 'Review process in progress'; }, nextStep() { if (this.application.everHadConcern || this.application.everHadEligibilityIssue) return 'Inspect the concern or eligibility clarification and make an explicit administrative decision.'; if (this.earlyEligible) return 'Accept after two reviews, complete the third review yourself, or wait for another reviewer.'; if (this.completedCount === 3) return 'Review the calculated outcome and any available intervention.'; if (this.completedCount === 2) return 'A third review is required because the early-acceptance checks are not met.'; return `Complete ${3 - this.completedCount} more independent review${3 - this.completedCount === 1 ? '' : 's'}, or use the separate senior bypass if justified.`; } }, methods: { yesNo(value) { return value ? 'Yes' : 'No'; }, thresholdCheck(slot) { if (!slot) return 'Waiting for review'; if (this.application.adminReviewsRevealed) return `${Math.round(slot.percentage)}% — ${slot.percentage >= 85 ? 'Yes' : 'No'}`; return slot.percentage >= 85 ? 'Qualifying score recorded' : 'Does not meet early-acceptance threshold'; }, scoreSummary(slot) { if (!this.application.adminReviewsRevealed) return slot.percentage >= 85 ? 'Qualifying score recorded' : 'Below early-acceptance threshold'; return `${Math.round(slot.percentage)}%`; }, slotStatus(slot) { return ({ available: 'Available', claimed: 'Claimed · not started', 'in-progress': 'In progress', submitted: 'Submitted', closed: this.application.acceptanceOrigin === 'Early acceptance' ? 'Closed because third review was waived' : 'Closed by admin decision' })[slot.state] || slot.state; }, formatDate(value) { return new Intl.DateTimeFormat('en-GB', { dateStyle: 'medium', timeStyle: 'short' }).format(new Date(value)); }, completeReview() { claimReview(); this.$router.push(this.reviewRoute); }, wait() { waitForThirdReview(); }, reveal() { if (window.confirm('Viewing existing reviews may influence an independent Admin assessment. Continue?')) revealCompletedReviews(); }, scenario(value) { loadDemoReviewScenario(value); this.$emit('reload'); }, reset() { resetDemoWorkflow(); this.$emit('reload'); }, confirmAction(reason) { if (this.action === 'early') acceptEarly(reason); else adminBypass(reason); this.action = ''; } } };</script>
